import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·19","description":"易小帖 - 卷四·19","frontmatter":{"title":"卷四·19","description":"易小帖 - 卷四·19"},"headers":[],"relativePath":"classics/yixiaotie/113.md","filePath":"classics/yixiaotie/113.md"}'),o={name:"classics/yixiaotie/113.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·19",tabindex:"-1"},[r("卷四·19 "),e("a",{class:"header-anchor",href:"#卷四·19","aria-label":"Permalink to “卷四·19”"},"​")],-1),e("p",null,"陰陽稱九六，舊俱不得其解。有謂乾體有三畫，坤體有六畫，陽得兼陰，故合三與六而稱九，陰不得兼陽，則但稱其數曰六而已。然此皆一邊之言，陽能兼陰，陰亦能兼陽，倘有人雲，陰兼三而成六，則其語詘矣。有謂九與六皆天地生數，天以一三五三數合之成九，地以二四兩數合之成六，所謂參天兩地而倚數是也。然此亦一邊之言。天地有生必有成，有一二三四五必有六七八九十，故曰五位相得而各有合。謂生與成合也。今但舉生數為言，則倘有人曰：吾用成數，地有六八十三數，天祗七九二數，則參地兩天矣。有謂八衍卦數，七衍蓍數，惟九六不極其衍，故發揮而為爻，則更是一邊無據之言。古並無有以七衍蓍者，推其意，不過謂蓍用四十有九，適七七之數耳。實則大衍五十，揲蓍亦五十，故五十是正數，所雲四十有九，猶之分二揲四扐一之節目耳，非衍數也。若論衍數，則以四揲九得三十六，以四揲六得二十四合之為五十蓍數，非七七矣。惟先仲氏解九六最為簡易，曰：卦成於三，三其三則為九，此參天也。兩其三則為六，此兩地也。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
